import sys
from openpyxl import load_workbook

path = "budget.xlsx"

# Dump raw structure (formulas as stored)
wb = load_workbook(path, data_only=False)
print("--- STRUCTURE (formulas) ---")
for ws in wb.worksheets:
    print(f"=== Sheet: {ws.title} | dims={ws.dimensions} | max_row={ws.max_row} | max_col={ws.max_column} ===")
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                print(f"{ws.title}!{cell.coordinate}: {cell.value!r}")

# Dump cached values (data_only) and per-column numeric sums
wb2 = load_workbook(path, data_only=True)
print("--- CACHED VALUES + NUMERIC SUMS ---")
for ws in wb2.worksheets:
    print(f"=== Sheet: {ws.title} ===")
    col_sums = {}
    for row in ws.iter_rows():
        for cell in row:
            v = cell.value
            if v is not None:
                print(f"{ws.title}!{cell.coordinate}: {v!r}")
                if isinstance(v, (int, float)):
                    col_sums[cell.column_letter] = col_sums.get(cell.column_letter, 0.0) + v
    for col, total in sorted(col_sums.items()):
        print(f"{ws.title}!{col} numeric sum: {total}")

